                 if all((r - s) % p or a == b
                        for r, a in known.items() for s, b in known.items()))
        vals = {}
        for r, color in known.items():
            vals[r % p] = color
        for k in range(p):
            if k not in vals:
                prev = max((x for x in vals if x < k), default=max(vals))
                vals[k] = vals[prev]
        return [[vals[r % p]] * w for r in range(h)]

    # Choose the diagonal direction whose bands have the fewest conflicts.
    options = []
    for sign in (1, -1):
        bands = {}
        conflicts = 0
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    key = c + sign * r
                    if key in bands and bands[key] != color:
                        conflicts += 1
                    bands[key] = color
        options.append((conflicts, sign, bands))

    _, sign, bands = min(options, key=lambda x: x[0])
    if not bands:
        return [row[:] for row in grid]

    # Find the shortest repeating color sequence compatible with all known
    # diagonal bands. The sequence is indexed by the diagonal offset.
    keys = list(bands)
    period = next(
        (p for p in range(1, 2 * max(h, w) + 1)
         if all((a - b) % p or bands[a] == bands[b]
                for a in keys for b in keys)),
        max(keys) - min(keys) + 1
    )
    vals = {}
    for key, color in bands.items():
        vals[key % period] = color

    # Fill unseen positions by continuing the ordered cyclic pattern.
    known = sorted(vals)
    for k in range(period):
        if k not in vals:
            prev = max((x for x in known if x < k), default=known[-1])
            vals[k] = vals[prev]

    return [[vals[(c + sign * r) % period] for c in range(w)]
            for r in range(h)]
